<div class="d-flex gap-2 align-items-center mb-3"><h2 class="h4 mb-0"><?= e($z['title']) ?></h2><a class="btn btn-outline-secondary ms-auto" href="<?= url('learn/' . (int)$z['section_subject_id']) ?>"><i class="bi bi-arrow-right"></i> رجوع</a></div>
