  <?php else: ?><div class="alert alert-secondary mb-0"><?= ['not_yet' => 'لم يُفتح الاختبار بعد.', 'closed' => 'انتهى وقت الاختبار.', 'open' => 'استنفدت محاولاتك.'][$z['state']] ?></div><?php endif; ?></div>
